spritejs='''const spec=SPEC; const load=s=>new Promise((r,j)=>{let i=new Image;i.onload=()=>r(i);i.onerror=j;i.src=s});
async function main(){let paper=await load('materials/paper.png'),stamp=await load('materials/stamp.png'),out={};
let seed=123;function rnd(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;}
for(const s of spec){let [w,h]=s.size,c=document.createElement('canvas');c.width=w;c.height=h;let x=c.getContext('2d');
if(s.slot==='stampRing'||s.slot==='stampSprite'){x.drawImage(stamp,0,0,w,h);if(s.tint==='white'){x.globalCompositeOperation='source-in';x.fillStyle='white';x.fillRect(0,0,w,h);x.globalCompositeOperation='source-over';}}
else if(s.slot==='paperPanel'||s.slot==='paperCard'){x.fillStyle='#332e2526';x.fillRect(2,3,w-2,h-3);x.drawImage(paper,0,0,w-3,h-4);x.fillStyle='#ded7c5';x.globalAlpha=.18;x.fillRect(2,2,w-7,h-8);x.globalAlpha=1;x.strokeStyle='#837b6438';x.lineWidth=1;x.strokeRect(.5,.5,w-4,h-5);}
else if(s.slot==='enamelPlate'){x.fillStyle='#b8c4bd';x.fillRect(0,0,w,h);x.fillStyle='#3d605e';x.fillRect(2,2,w-4,h-4);for(let i=0;i<80;i++){x.fillStyle='#c6c3ad';x.fillRect(Math.floor(rnd()*w),rnd()<.5?Math.floor(rnd()*5):h-1-Math.floor(rnd()*5),2,1);}x.fillStyle='#a8a894';x.fillRect(5,5,2,2);x.fillRect(w-7,h-7,2,2);}
else {x.fillStyle=s.slot.includes('Track')?'#9b9b9b':'#eeeeee';x.fillRect(0,0,w,h);x.strokeStyle='#bcbcbc';x.lineWidth=1;x.strokeRect(.5,.5,w-1,h-1);for(let i=0;i<w*h/25;i++){let v=185+Math.floor(rnd()*60);x.fillStyle=`rgba(${v},${v},${v},.16)`;x.fillRect(Math.floor(rnd()*w),Math.floor(rnd()*h),1,1);}if(s.slot==='slipHeader'){x.fillStyle='#888';for(let i=10;i<w-10;i+=7)x.fillRect(i,h-12,3,1);}}
out[s.slot]=c.toDataURL('image/png');}
document.getElementById('data').textContent=JSON.stringify(out);document.title='DONE';}main();'''.replace('SPEC',json.dumps(spec))
(R/'sprite-export.html').write_text('<html><body><pre id="data"></pre><script>'+spritejs+'</script></body></html>',encoding='utf-8')
cmd=[CHROME,'--headless','--disable-gpu','--no-first-run','--allow-file-access-from-files','--user-data-dir='+PROFILE,'--virtual-time-budget=3000','--dump-dom',(R/'sprite-export.html').as_uri()]
result=subprocess.run(cmd,capture_output=True,check=True).stdout.decode('utf-8')
payload=json.loads(html.unescape(re.search(r'<pre id="data">(.*?)</pre>',result,re.S).group(1)))
for name,data in payload.items():(R/'sprites'/f'{name}.png').write_bytes(base64.b64decode(data.split(',',1)[1]))

